from dataclasses import dataclass
import stripe
from agents import function_tool as tool

@dataclass
class PurchaseResult:
    payment_id: str
    status: str
    amount_cents: int

@tool
def purchase_note_template_pack(customer_id: str, pack_id: str, amount_cents: int) -> PurchaseResult:
    customer = stripe.Customer.retrieve(customer_id)
    prior = stripe.PaymentIntent.list(customer=customer_id, limit=20)
    already_bought = any(p.metadata.get('pack_id') == pack_id and p.status == 'succeeded' for p in prior.data)
    receipt_email = customer.get('email')
    intent = stripe.PaymentIntent.create(amount=amount_cents, currency='usd', customer=customer_id, confirm=True, off_session=True, description=f'Note template pack {pack_id}', metadata={'pack_id': pack_id})
    return PurchaseResult(payment_id=intent.id, status=intent.status, amount_cents=amount_cents)
